import { useState } from "react";
import { Heart, Eye, ArrowUpDown } from "lucide-react";
import { siteConfig } from "../config/site";
import { Header } from "../components/Header";
import { Footer } from "../components/Footer";

type SortOption =
  | "Featured"
  | "Most liked"
  | "Most comments"
  | "Most viewed"
  | "Most recent";
type TimeFilter = "All time" | "This week" | "This month" | "This year";

const sortOptions: SortOption[] = [
  "Featured",
  "Most liked",
  "Most comments",
  "Most viewed",
  "Most recent",
];
const timeFilters: TimeFilter[] = [
  "All time",
  "This week",
  "This month",
  "This year",
];
const creativeFields = [
  "All",
  "2D Animation",
  "3D",
  "Illustration",
  "Photography",
  "Graphic Design",
  "Watercolor Painting",
  "Embroidery",
  "Craft",
  "Digital Illustration",
  "Architecture",
];

export default function Projects() {
  const [sortBy, setSortBy] = useState<SortOption>("Featured");
  const [timeFilter, setTimeFilter] = useState<TimeFilter>("All time");
  const [fieldFilter, setFieldFilter] = useState("All");
  const [dropdownOpen, setDropdownOpen] = useState(false);

  let displayed = [...siteConfig.projects];

  if (fieldFilter !== "All") {
    displayed = displayed.filter(
      (p) =>
        p.field === fieldFilter ||
        (fieldFilter === "Craft" && p.field === "Craft") ||
        (fieldFilter === "Digital Illustration" &&
          p.field === "Digital Illustration")
    );
  }

  switch (sortBy) {
    case "Most liked":
      displayed.sort((a, b) => b.likes - a.likes);
      break;
    case "Most viewed":
      displayed.sort((a, b) => b.views - a.views);
      break;
    case "Most recent":
      displayed.reverse();
      break;
    default:
      break;
  }

  const formatViews = (n: number) => {
    if (n >= 1000) return (n / 1000).toFixed(n >= 10000 ? 0 : 1) + "K";
    return String(n);
  };

  return (
    <div className="min-h-screen bg-surface grain">
      <Header activePage="projects" />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
