  --color-border: #e5e5e5;
  --color-border-strong: #d4d4d4;
  --color-accent-teal: #00c9a7;
  --color-accent-green: #00d084;
  --color-winner: #f59e0b;

  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.25rem;
}

@font-face {
  font-family: "Plus Jakarta Sans";
  src: url("https://fonts.gstatic.com/s/plusjakartasans/v8/LDIoa08I4i7WVMVgRNS7Z47RfO7T9V7sHfE.woff2")
    format("woff2");
  font-weight: 400 800;
  font-display: swap;
}

@font-face {
  font-family: "Space Grotesk";
  src: url("https://fonts.gstatic.com/s/spacegrotesk/v16/V8mQoQDjQSkFtoMM3T6r8E7mF71Q-gOoraIAEj7oUXskPMBBSSJLm2E.woff2")
    format("woff2");
  font-weight: 400 700;
  font-display: swap;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-ink);
  background: var(--color-surface);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Carousel */
.carousel-track {
  display: flex;
  gap: 1rem;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Scrollbar hide */
.scrollbar-hide {
  -ms-overflow-style: none;
  scrollbar-width: none;
}
.scrollbar-hide::-webkit-scrollbar {
  display: none;
}

/* Grain overlay */
.grain::before {
  content: "";
  position: fixed;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  opacity: 0.025;
  pointer-events: none;
  z-index: 9999;
}

/* Card hover lift */
.card-lift {
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.card-lift:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px -8px rgba(0, 0, 0, 0.15);
}

/* Button press */
.btn-press:active {
  transform: scale(0.97);
}

/* Focus ring */
.focus-ring:focus-visible {
  outline: 2px solid var(--color-brand);
  outline-offset: 2px;
}

/* Pricing toggle */
.pricing-toggle-btn {
  position: relative;
  transition: color 0.2s ease;
}
.pricing-toggle-btn.active::after {
  content: "";
  position: absolute;
  bottom: -2px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-brand);
  border-radius: 2px;
}

/* Masonry */
.masonry-grid {
  column-count: 3;
  column-gap: 1rem;
}
@media (max-width: 1024px) {
  .masonry-grid {
    column-count: 2;
  }
}
@media (max-width: 640px) {
  .masonry-grid {
    column-count: 1;
  }
}
.masonry-item {
  break-inside: avoid;
  margin-bottom: 1rem;
}

/* Footer accordion mobile */
@media (max-width: 768px) {
  .footer-section-content {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.3s ease;
  }
  .footer-section-content.open {
    grid-template-rows: 1fr;
  }
  .footer-section-content > div {
    overflow: hidden;
  }
}
@media (min-width: 769px) {
  .footer-section-content {
    grid-template-rows: 1fr !important;
  }
  .footer-section-content > div {
    overflow: visible;
  }
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.animate-fade-in-up {
  animation: fadeInUp 0.6s ease both;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
.animate-slide-in {
  animation: slideIn 0.5s ease both;
}

/* Countdown banner */
.countdown-banner {
  background: linear-gradient(90deg, #f02d00 0%, #ff5c33 100%);
}

/* Badge styles */
.badge-discount {
  background: #fee2e2;
  color: #991b1b;
}
.badge-bestseller {
  background: #fef3c7;
  color: #92400e;
}
.badge-new {
  background: #d1fae5;
  color: #065f46;
}
.badge-winner {
  background: #fef3c7;
  color: #92400e;
}

/* Image placeholder gradient */
.img-placeholder {
  background: linear-gradient(135deg, #f3f4f6 0%, #e5e7eb 100%);
}
